create table if not exists public.business_intelligence_evidence (id uuid primary key default gen_random_uuid(), workspace_id uuid not null, business_id uuid, source_type text not null, source_uri text, source_external_id text, observed_at timestamptz not null default now(), content_hash text, extracted_data jsonb not null default '{}'::jsonb, provider text, confidence numeric(5,4) not null default 0.5 check (confidence >= 0 and confidence <= 1), verification_status text not null default 'unverified' check (verification_status in ('unverified','corroborated','verified','conflicted','rejected')), verified_by text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()); create index if not exists idx_brain_evidence_workspace_observed on public.business_intelligence_evidence(workspace_id, observed_at desc); alter table public.business_intelligence_evidence enable row level security; create policy "members_read_business_intelligence_evidence" on public.business_intelligence_evidence for select to authenticated using (public.is_workspace_member(auth.uid(), workspace_id));;
